-- Row-level archive of the tables dropped on 2026-08-19.
--
-- `DbSnapshot` tracks table SIZES, not contents, so it is not a backup — these
-- rows had no other copy. Everything below is restorable by running this file.
--
-- Why they were dropped: the 2026-08-17 audit established zero readers and
-- removed the models from schema.prisma, but left the tables in the database.
-- That drift made `prisma db push` refuse to run without --accept-data-loss,
-- which turned a routine additive migration into a hazard: the next person to
-- add a column would have been one flag away from deleting these tables anyway,
-- with no archive at all.


-- InvoiceSyncLog
CREATE TABLE IF NOT EXISTS "InvoiceSyncLog" ("id" text NOT NULL, "startedAt" timestamp without time zone NOT NULL, "completedAt" timestamp without time zone, "emailsScanned" integer NOT NULL, "invoicesCreated" integer NOT NULL, "invoicesSkipped" integer NOT NULL, "errors" integer NOT NULL, "errorDetails" text, "triggeredBy" text NOT NULL);

